if(!moduleDir.startsWith(root+path.sep))throw Error('Test module must remain inside this workspace');
const instance='test-'+Date.now(),data=path.join(moduleDir,'.local',instance),connection=path.join(data,'connection.json');
const output=path.join(root,'.planning/windows-session-desk-tests');fs.mkdirSync(output,{recursive:true});
