const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function start(){server=cp.spawn(ps,args,{windowsHide:true,stdio:'ignore'});for(let i=0;i<100;i++){if(fs.existsSync(connection)){const c=JSON.parse(fs.readFileSync(connection,'utf8'));if(c.pid===server.pid){[base,token]=c.url.split('#');return;}}if(server.exitCode!==null)throw Error('server startup failed: '+(fs.existsSync(path.join(data,'startup-error.txt'))?fs.readFileSync(path.join(data,'startup-error.txt'),'utf8'):'unknown'));await delay(100);}throw Error('startup timeout');}
async function api(route,body,headers={}){const response=await fetch(base+route,{method:body===undefined?'GET':'POST',headers:{'X-SessionDesk':token,...(body===undefined?{}:{'Content-Type':'application/json'}),...headers},body:body===undefined?undefined:JSON.stringify(body)});return {status:response.status,data:await response.json()};}
async function stop(){if(server&&server.exitCode===null){try{await api('api/shutdown',{});}catch{}for(let i=0;i<100&&server.exitCode===null;i++)await delay(50);if(server.exitCode===null){server.kill();throw Error('service did not stop gracefully');}}}
