browser=await chromium.launch({channel:'msedge',headless:true});const page=await browser.newPage();const errors=[];let external=0;page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(/^https?:/.test(r.url())&&!r.url().startsWith(base))external++;});
await page.goto(base+'#'+token);await page.waitForFunction(()=>document.getElementById('notice').textContent.includes('已连接'));
