await page.locator('#project').fill('虚构项目1');await save(1,'资料整理 · 北岸');assert.equal(await page.locator('#id').inputValue(),'');await save(2,'资料整理 · 灯塔');await save(3,'缺失日志验证');assert.equal((await api('api/tasks')).data.tasks.length,4);passed('save optional project name and ID and reset add form');
