await page.locator(`[data-query="${id(1)}"]`).click();const repeat=await api('api/query',{id:id(1)});assert.equal(repeat.status,200);const firstRun=repeat.data.run;assert.equal((await api('api/query',{id:id(1)})).data.run,firstRun);passed('duplicate running query reuses job');
