await page.locator('#reportButton').click();await page.waitForFunction(()=>!document.getElementById('reportPanel').hidden);assert.match(await page.locator('#report').textContent(),/这是隔离的虚构测试输入/);passed('local detailed report');
await page.locator(`[data-query="${id(3)}"]`).click();await page.waitForFunction(()=>document.getElementById('status').textContent==='查询失败',{},{timeout:20000});assert.equal(await page.locator('#reportButton').isDisabled(),true);assert.doesNotMatch(await page.locator('#output').textContent(),/虚构会话 2/);passed('missing synthetic session fails without stale output');
assert.equal((await api('api/tasks',{action:'save',id:'x; calc',name:'bad'})).status,400);assert.equal((await api('api/query',{id:id(4)})).status,400);assert.equal((await api('api/report?id=../../tasks.json')).status,404);passed('invalid IDs unsupported data and arbitrary report paths rejected');
await page.locator(`[data-edit="${id(1)}"]`).click();assert.equal(await page.locator('#id').getAttribute('readonly'),'');await page.locator('#name').fill('重命名后保留');await page.locator('#save').click();await page.waitForFunction(()=>!document.getElementById('save').disabled);assert.equal((await api('api/tasks')).data.tasks.length,20);assert.equal((await api('api/tasks')).data.tasks.find(t=>t.id===id(1)).name,'重命名后保留');passed('explicit edit keeps ID fixed and preserves other 19 tasks');
await api('api/tasks',{action:'delete',id:id(4)});passed('delete task');
await page.screenshot({path:path.join(output,'local-only.png'),fullPage:true});
