await page.locator(`[data-query="${id(1)}"]`).click();await page.waitForFunction(()=>document.getElementById('status').textContent==='查询完成',{},{timeout:20000});passed('query after restart');
await page.locator('[data-lang="en-US"]').click();await page.waitForFunction(()=>document.getElementById('status').textContent==='Query complete',{},{timeout:20000});assert.equal(await page.locator('html').getAttribute('lang'),'en-US');const englishJob=(await api('api/job?id='+id(1))).data;assert.equal(englishJob.language,'en-US');assert.equal(await page.locator('#output').textContent(),englishJob.output);assert.doesNotMatch(englishJob.output,/一、基本信息/);assert.match(englishJob.output,/Basic|Task|Session/);
const directEn=cp.spawnSync(ps,['-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',path.join(data,'runtime/Invoke-IsolatedAnalyzer.ps1'),'-TaskId',id(1),'-ReportPath',path.join(data,'reports',id(1)+'.md'),'-Language','en-US'],{encoding:'utf8',windowsHide:true,timeout:20000});assert.equal(directEn.status,0,directEn.stderr);assert.equal(directEn.stdout,englishJob.output);await page.locator('#reportButton').click();await page.waitForFunction(()=>!document.getElementById('reportPanel').hidden);assert.match(await page.locator('#report').textContent(),/Task|Session/);assert.match(await page.locator('#report').textContent(),/这是隔离的虚构测试输入/);passed('English UI terminal and report; source data retained; direct output matches');
